          "code": "import numpy as np\n\ndef confusion(pred, target, n_classes):\n    k = (target >= 0) & (target < n_classes)\n    return np.bincount(n_classes * target[k].astype(int) + pred[k],\n                       minlength=n_classes**2).reshape(n_classes, n_classes)\n\ndef metrics(cm):\n    tp = np.diag(cm)\n    fp, fn = cm.sum(0) - tp, cm.sum(1) - tp\n    iou  = tp / np.maximum(tp + fp + fn, 1)\n    dice = 2 * tp / np.maximum(2 * tp + fp + fn, 1)\n    return iou, dice, tp.sum() / cm.sum()\n\ncm = confusion(pred, target, n_classes=3)          # classes: background, road, pedestrian\niou, dice, pix_acc = metrics(cm)\nprint('per-class IoU :', iou.round(3))             # [0.982 0.874 0.412]\nprint('mIoU          :', iou.mean().round(3))      # 0.756\nprint('pixel accuracy:', round(pix_acc, 3))        # 0.971  <- useless: background dominates\n# The rare class (pedestrian, IoU 0.41) is the one that matters and the one the\n# mean hides. ALWAYS report per-class numbers, not just the mean.",
