          "code": "import torch, torch.nn as nn\n\nclass ASPP(nn.Module):\n    \"\"\"Atrous Spatial Pyramid Pooling: parallel dilated convs + image-level context.\"\"\"\n    def __init__(self, cin, cout=256, rates=(1, 6, 12, 18)):\n        super().__init__()\n        self.branches = nn.ModuleList([\n            nn.Sequential(nn.Conv2d(cin, cout, 3 if r > 1 else 1,\n                                    padding=r if r > 1 else 0, dilation=r, bias=False),\n                          nn.BatchNorm2d(cout), nn.ReLU(inplace=True)) for r in rates])\n        self.pool = nn.Sequential(nn.AdaptiveAvgPool2d(1),        # global context branch\n                                  nn.Conv2d(cin, cout, 1, bias=False),\n                                  nn.BatchNorm2d(cout), nn.ReLU(inplace=True))\n        self.project = nn.Sequential(nn.Conv2d(cout * (len(rates) + 1), cout, 1, bias=False),\n                                     nn.BatchNorm2d(cout), nn.ReLU(inplace=True))\n\n    def forward(self, x):\n        feats = [b(x) for b in self.branches]\n        g = nn.functional.interpolate(self.pool(x), size=x.shape[-2:], mode='bilinear',\n                                      align_corners=False)\n        return self.project(torch.cat(feats + [g], dim=1))\n\n# a 3x3 conv with dilation r has the receptive field of a (2r+1) kernel at 9 weights:\nfor r in (1, 6, 12, 18):\n    print(f'rate {r:2d} -> effective kernel {2*r+1:2d}x{2*r+1:<2d} with 9 weights')",
